    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int wpb = blockDim.x >> 5;
    const int mid = blockIdx.x * wpb + warp;   // matrix index
    if (mid >= B) return;

